import { Component, computed, ElementRef, HostBinding, inject } from '@angular/core';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
  host: {
    '[tabindex]': 'order()',
  },
})
export class PctAvatar {
  protected readonly order = computed(() => 0);
  constructor() {
    const self = this as any;
    Object.assign(self, { order: computed(() => 5) });
  }
}
